// snd_channel.c -- sound effects started with S_StartSound
//
// Every call queues a playsound. Once it is due, the playsound is
// given a channel, and every channel owns one OpenAL source.

#include "client.h"
#include "snd_loc.h"

#define MAX_CHANNELS        64
#define MAX_PLAYSOUNDS      128

// the original mixer turned attenuation levels into distance multipliers
#define ATTENUATION_SCALE           0.0005f
#define ATTENUATION_SCALE_STATIC    0.001f

#define SOUND_NO_DELAY      0.0f
#define CHANNEL_NEVER_ENDS  0x7fffffff

// a playsound is generated by each call to S_StartSound and
// assigned to a channel once cls.realtime reaches begin
typedef struct playsound_s
{
    struct playsound_s  *prev, *next;
    sfx_t       *sfx;
    float       volume;         // 0-1
    float       attenuation;
    int         entnum;
    int         entchannel;
    qboolean    fixed_origin;   // use origin field instead of entnum's origin
    vec3_t      origin;
    int         begin;          // cls.realtime to start at
} playsound_t;

typedef struct
{
    ALuint      source;
    sfx_t       *sfx;           // NULL = free
    int         end;            // cls.realtime when the sound is over
    int         entnum;         // to allow overriding a specific sound
    int         entchannel;
    vec3_t      origin;         // only used if fixed_origin is set
    vec_t       dist_mult;      // distance multiplier (attenuation/clipK)
    qboolean    fixed_origin;   // use origin instead of fetching entnum's origin
} channel_t;

static channel_t    channels[MAX_CHANNELS];

static playsound_t  playsounds[MAX_PLAYSOUNDS];
static playsound_t  free_playsounds;
static playsound_t  pending_playsounds;    // sorted by begin


static int S_ViewEntity (void)
{
    return cl.playernum + 1;
}

/*
===============================================================================

Playsound queue

===============================================================================
*/

static void S_ResetPlaysounds (void)
{
    memset (playsounds, 0, sizeof(playsounds));
    free_playsounds.next = free_playsounds.prev = &free_playsounds;
    pending_playsounds.next = pending_playsounds.prev = &pending_playsounds;

    for (int i = 0; i < MAX_PLAYSOUNDS; i++)
    {
        playsounds[i].prev = &free_playsounds;
        playsounds[i].next = free_playsounds.next;
        playsounds[i].prev->next = &playsounds[i];
        playsounds[i].next->prev = &playsounds[i];
    }
}

static playsound_t *S_AllocPlaysound (void)
{
    playsound_t *ps = free_playsounds.next;
    if (ps == &free_playsounds)
        return NULL;        // no free playsounds

    // unlink from freelist
    ps->prev->next = ps->next;
    ps->next->prev = ps->prev;

    return ps;
}

static void S_FreePlaysound (playsound_t *ps)
{
    // unlink from the pending list
    ps->prev->next = ps->next;
    ps->next->prev = ps->prev;

    // add to free list
    ps->next = free_playsounds.next;
    free_playsounds.next->prev = ps;
    ps->prev = &free_playsounds;
    free_playsounds.next = ps;
}

static void S_QueuePlaysound (playsound_t *ps)
{
    playsound_t *sort = pending_playsounds.next;
    while (sort != &pending_playsounds && sort->begin <= ps->begin)
        sort = sort->next;

    ps->next = sort;
    ps->prev = sort->prev;
    ps->next->prev = ps;
    ps->prev->next = ps;
}


/*
===============================================================================

Channels

===============================================================================
*/

static void S_StopChannel (channel_t *ch)
{
    ALuint source = ch->source;
    S_StopSource (source);
    memset (ch, 0, sizeof(*ch));
    ch->source = source;
}

/*
=================
S_PickChannel

Same priorities as the original mixer: a sound on the same entity
channel is replaced, CHAN_AUTO never overrides, monsters never cut
off the player, otherwise the sound closest to its end makes room.
=================
*/
static channel_t *S_PickChannel (int entnum, int entchannel)
{
    if (entchannel < 0)
        Com_Error (ERR_DROP, "S_PickChannel: entchannel<0");

    channel_t *best = NULL;
    int best_life_left = CHANNEL_NEVER_ENDS;

    for (int i = 0; i < MAX_CHANNELS; i++)
    {
        channel_t *ch = &channels[i];

        if (entchannel != CHAN_AUTO && ch->entnum == entnum && ch->entchannel == entchannel)
        {
            best = ch;
            break;
        }

        if (!ch->sfx)
        {
            best = ch;
            best_life_left = -CHANNEL_NEVER_ENDS;
            continue;
        }

        if (ch->entnum == S_ViewEntity () && entnum != S_ViewEntity ())
            continue;

        int life_left = ch->end - cls.realtime;
        if (life_left < best_life_left)
        {
            best_life_left = life_left;
            best = ch;
        }
    }

    if (best)
        S_StopChannel (best);

    return best;
}

static void S_ChannelOrigin (const channel_t *ch, vec3_t origin)
{
    if (ch->fixed_origin)
        VectorCopy (ch->origin, origin);
    else
        CL_GetEntitySoundOrigin (ch->entnum, origin);
}

/*
=================
S_SpatializeChannel

Moves the channel's source to where its sound comes from.
Returns false once the sound is out of range.
=================
*/
static qboolean S_SpatializeChannel (channel_t *ch)
{
    // anything coming from the view entity will always be full volume
    if (ch->entnum == S_ViewEntity () || !S_IsSpatialized (ch->dist_mult))
    {
        S_PlaceSourceOnListener (ch->source);
        return true;
    }

    vec3_t origin;
    S_ChannelOrigin (ch, origin);
    S_PlaceSourceInWorld (ch->source, origin, ch->dist_mult);
    return S_IsInRange (origin, ch->dist_mult);
}

static float S_DistanceMultiplier (float attenuation)
{
    if (attenuation == ATTN_STATIC)
        return attenuation * ATTENUATION_SCALE_STATIC;
    return attenuation * ATTENUATION_SCALE;
}

static int S_SoundDuration (const sfx_t *sfx)
{
    return sfx->length * MS_PER_SECOND / sfx->rate;
}

/*
===============
S_IssuePlaysound

Takes a due playsound and begins it on a channel
===============
*/
static void S_IssuePlaysound (playsound_t *ps)
{
    if (s_show->value)
        Com_Printf ("Issue %i\n", ps->begin);

    channel_t *ch = S_PickChannel (ps->entnum, ps->entchannel);
    if (!ch || !S_LoadSound (ps->sfx))
    {
        S_FreePlaysound (ps);
        return;
    }

    ch->dist_mult = S_DistanceMultiplier (ps->attenuation);
    ch->entnum = ps->entnum;
    ch->entchannel = ps->entchannel;
    ch->sfx = ps->sfx;
    VectorCopy (ps->origin, ch->origin);
    ch->fixed_origin = ps->fixed_origin;

    // sounds with a cue chunk keep looping until something overrides them
    qboolean loops = ch->sfx->loopstart != NO_LOOP_START;
    ch->end = loops ? CHANNEL_NEVER_ENDS : cls.realtime + S_SoundDuration (ch->sfx);

    S_SpatializeChannel (ch);
    alSourcei (ch->source, AL_BUFFER, ch->sfx->buffer);
    alSourcei (ch->source, AL_LOOPING, loops);
    alSourcef (ch->source, AL_GAIN, ps->volume);
    alSourcePlay (ch->source);

    S_FreePlaysound (ps);
}

static void S_IssueDuePlaysounds (void)
{
    for (;;)
    {
        playsound_t *ps = pending_playsounds.next;
        if (ps == &pending_playsounds || ps->begin > cls.realtime)
            break;
        S_IssuePlaysound (ps);
    }
}

static qboolean S_ChannelFinished (const channel_t *ch)
{
    ALint state;
    alGetSourcei (ch->source, AL_SOURCE_STATE, &state);
    return state == AL_STOPPED;
}


/*
===============================================================================

Interface for the rest of the sound backend

===============================================================================
*/

qboolean S_InitChannels (void)
{
    ALuint sources[MAX_CHANNELS];

    alGetError ();
    alGenSources (MAX_CHANNELS, sources);
    if (alGetError () != AL_NO_ERROR)
    {
        Com_Printf ("S_InitChannels: can't allocate %i OpenAL sources\n", MAX_CHANNELS);
        return false;
    }

    memset (channels, 0, sizeof(channels));
    for (int i = 0; i < MAX_CHANNELS; i++)
        channels[i].source = sources[i];

    S_ResetPlaysounds ();
    return true;
}

void S_ShutdownChannels (void)
{
    S_StopAllChannels ();
    for (int i = 0; i < MAX_CHANNELS; i++)
        alDeleteSources (1, &channels[i].source);
    memset (channels, 0, sizeof(channels));
}

void S_UpdateChannels (void)
{
    S_IssueDuePlaysounds ();

    for (int i = 0; i < MAX_CHANNELS; i++)
    {
        channel_t *ch = &channels[i];
        if (!ch->sfx)
            continue;

        if (S_ChannelFinished (ch) || !S_SpatializeChannel (ch))
            S_StopChannel (ch);
    }
}

void S_StopAllChannels (void)
{
    S_ResetPlaysounds ();
    for (int i = 0; i < MAX_CHANNELS; i++)
        S_StopChannel (&channels[i]);
}

void S_StopChannelsUsing (sfx_t *sfx)
{
    for (int i = 0; i < MAX_CHANNELS; i++)
    {
        if (channels[i].sfx == sfx)
            S_StopChannel (&channels[i]);
    }
}

void S_PrintChannels (void)
{
    for (int i = 0; i < MAX_CHANNELS; i++)
    {
        if (channels[i].sfx)
            Com_Printf ("%3i %s\n", channels[i].entnum, channels[i].sfx->name);
    }
}


/*
===============================================================================

Public interface (sound.h)

===============================================================================
*/

/*
====================
S_StartSound

Validates the parms and queues the sound up
if origin is NULL, the sound will be dynamically sourced from the entity
Entchannel 0 will never override a playing sound
====================
*/
void S_StartSound (vec3_t origin, int entnum, int entchannel, sfx_t *sfx, float fvol, float attenuation, float timeofs)
{
    if (!sound_started || !sfx)
        return;

    if (S_IsPlayerSoundPlaceholder (sfx))
        sfx = S_RegisterPlayerSound (&cl_entities[entnum].current, sfx->name);

    if (!S_LoadSound (sfx))
        return;     // couldn't load the sound's data

    playsound_t *ps = S_AllocPlaysound ();
    if (!ps)
        return;

    ps->fixed_origin = origin != NULL;
    if (origin)
        VectorCopy (origin, ps->origin);
    ps->entnum = entnum;
    ps->entchannel = entchannel;
    ps->attenuation = attenuation;
    ps->volume = fvol;
    ps->sfx = sfx;
    ps->begin = cls.realtime + (int)(timeofs * MS_PER_SECOND);

    S_QueuePlaysound (ps);
}

void S_StartLocalSound (char *sound)
{
    if (!sound_started)
        return;

    sfx_t *sfx = S_RegisterSound (sound);
    if (!sfx)
    {
        Com_Printf ("S_StartLocalSound: can't cache %s\n", sound);
        return;
    }
    S_StartSound (NULL, S_ViewEntity (), CHAN_AUTO, sfx, SOUND_VOLUME_FULL, ATTN_NORM, SOUND_NO_DELAY);
}

// "play <sound> [sound...]", the .wav extension is optional
void S_PlaySoundCommand (void)
{
    for (int i = 1; i < Cmd_Argc (); i++)
    {
        char *arg = Cmd_Argv (i);
        char name[MAX_QPATH];

        if (strrchr (arg, '.'))
            Com_sprintf (name, sizeof(name), "%s", arg);
        else
            Com_sprintf (name, sizeof(name), "%s.wav", arg);

        S_StartLocalSound (name);
    }
}
